60	@RestController
61	@CrossOrigin(exposedHeaders = "errors, content-type")
62	@RequestMapping("/api")
63	public class OwnerRestControllerV1 implements OwnersApi {
64	
65	    private final ClinicService clinicService;
66	
67	    private final OwnerMapper ownerMapper;
68	
69	    private final PetMapper petMapper;
70	
71	    private final VisitMapper visitMapper;
72	
73	    public OwnerRestControllerV1(ClinicService clinicService,
74	                                 OwnerMapper ownerMapper,
75	                                 PetMapper petMapper,
76	                                 VisitMapper visitMapper) {
77	        this.clinicService = clinicService;
78	        this.ownerMapper = ownerMapper;
79	        this.petMapper = petMapper;
80	        this.visitMapper = visitMapper;
81	    }
82	
83	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
84	    @Override
85	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
86	        Collection<Owner> owners;
87	        if (lastName != null) {
88	            owners = this.clinicService.findOwnerByLastName(lastName);
89	        } else {
90	            owners = this.clinicService.findAllOwners();
91	        }
92	        if (owners.isEmpty()) {
93	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
94	        }
95	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
96	    }
97	
98	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
99	    @Override
100	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
101	        Owner owner = this.clinicService.findOwnerById(ownerId);
102	        if (owner == null) {
103	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
104	        }
105	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
106	    }
107	
108	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
109	    @Override
110	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
111	        prepareNewOwner(ownerFieldsDto);
112	        HttpHeaders headers = new HttpHeaders();
113	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
114	        if (owner.getRegistrationDate() == null) {
115	            owner.setRegistrationDate(LocalDate.now());
116	        }
117	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
118	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
119	        assignHousehold(owner, ownerFieldsDto);
120	        this.clinicService.saveOwner(owner);
121	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
122	        headers.setLocation(UriComponentsBuilder.newInstance()
123	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
124	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
125	    }
126	
127	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
128	    @Override
129	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
130	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
131	        if (currentOwner == null) {
132	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
133	        }
134	        currentOwner.setAddress(ownerFieldsDto.getAddress());
135	        currentOwner.setCity(ownerFieldsDto.getCity());
136	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
137	        currentOwner.setLastName(ownerFieldsDto.getLastName());
138	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
139	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
140	        this.clinicService.saveOwner(currentOwner);
141	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
142	    }
143	
144	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
145	    @Transactional
146	    @Override
147	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
148	        Owner owner = this.clinicService.findOwnerById(ownerId);
149	        if (owner == null) {
150	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
151	        }
152	        this.clinicService.deleteOwner(owner);
153	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
154	    }
155	
156	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
157	    @Override
158	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
159	        Owner owner = this.clinicService.findOwnerById(ownerId);
160	        if (owner == null) {
161	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
162	        }
163	        HttpHeaders headers = new HttpHeaders();
164	        Pet pet = petMapper.toPet(petFieldsDto);
165	        owner.setId(ownerId);
166	        pet.setOwner(owner);
167	        pet.getType().setName(null);
168	        this.clinicService.savePet(pet);
169	        PetDto petDto = petMapper.toPetDto(pet);
170	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
171	            .buildAndExpand(pet.getId()).toUri());
172	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
173	    }
174	
175	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
176	    @Override
177	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
178	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
179	        if (currentOwner != null) {
180	            Pet currentPet = this.clinicService.findPetById(petId);
181	            if (currentPet != null) {
182	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
183	                currentPet.setName(petFieldsDto.getName());
184	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
185	                this.clinicService.savePet(currentPet);
186	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
187	            }
188	        }
189	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
190	    }
191	
192	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
193	    @Override
194	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
195	        HttpHeaders headers = new HttpHeaders();
196	        Visit visit = visitMapper.toVisit(visitFieldsDto);
197	        Pet pet = new Pet();
198	        pet.setId(petId);
199	        visit.setPet(pet);
200	        this.clinicService.saveVisit(visit);
201	        VisitDto visitDto = visitMapper.toVisitDto(visit);
202	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
203	            .buildAndExpand(visit.getId()).toUri());
204	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
205	    }
206	
207	
208	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
209	    @Override
210	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
211	        Owner owner = this.clinicService.findOwnerById(ownerId);
212	        if (owner != null) {
213	            Pet pet = owner.getPet(petId);
214	            if (pet != null) {
215	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
216	            }
217	        }
218	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
219	    }
220	
221	    /**
222	     * Applies the intake rules a newly submitted owner must satisfy before it is persisted.
223	     * The address is normalized in place (so a required-field check that follows rejects an
224	     * address blank after normalization), the required fields are checked, the telephone and
225	     * email are normalized in place, and the resulting telephone is rejected when it already
226	     * belongs to another owner. Each rule
227	     * signals a violation by throwing, which the exception advice renders as the matching 4xx
228	     * response; when the method returns normally {@code ownerFieldsDto} is normalized and ready
229	     * to be mapped and saved.
230	     *
231	     * @param ownerFieldsDto the submitted owner fields, normalized in place
232	     */
233	    private void prepareNewOwner(OwnerFieldsDto ownerFieldsDto) {
234	        ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
235	        validateRequiredFields(ownerFieldsDto);
236	        ownerFieldsDto.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
237	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
238	        rejectDuplicateTelephone(ownerFieldsDto.getTelephone());
239	        rejectDuplicateHousehold(ownerFieldsDto);
240	        rejectCityAtCapacity(ownerFieldsDto.getCity());
241	        rejectDailyLimitExceeded();
242	    }
243	
244	    /**
245	     * The maximum number of owners that may be created on a single day. Once this many owners
246	     * already carry today's {@code registrationDate}, no further owner may be created today.
247	     */
248	    private static final long DAILY_OWNER_LIMIT = 100L;
249	
250	    /**
251	     * Rejects a new owner when {@link #DAILY_OWNER_LIMIT} or more owners have already been created
252	     * today, counted by {@code registrationDate} against the current date. When the limit has been
253	     * reached a {@link DailyOwnerLimitExceededException} is thrown, which the exception advice
254	     * renders as a 429 Too Many Requests response.
255	     */
256	    private void rejectDailyLimitExceeded() {
257	        LocalDate today = LocalDate.now();
258	        long count = this.clinicService.findAllOwners().stream()
259	            .filter(existing -> today.equals(existing.getRegistrationDate()))
260	            .count();
261	        if (count >= DAILY_OWNER_LIMIT) {
262	            throw new DailyOwnerLimitExceededException(today);
263	        }
264	    }
265	
266	    /**
267	     * The maximum number of owners a single city may hold. Once a city already contains this
268	     * many owners, no further owner may be created in it.
269	     */
270	    private static final long CITY_OWNER_CAPACITY = 50L;
271	
272	    /**
273	     * Rejects a new owner whose city already contains {@link #CITY_OWNER_CAPACITY} or more owners.
274	     * Cities are compared case-insensitively, consistent with how per-city owners are counted
275	     * elsewhere. When the city is at capacity a {@link CityCapacityExceededException} is thrown,
276	     * which the exception advice renders as a 409 Conflict response.
277	     *
278	     * @param city the city of the owner being created
279	     */
280	    private void rejectCityAtCapacity(String city) {
281	        long count = this.clinicService.findAllOwners().stream()
282	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
283	            .count();
284	        if (count >= CITY_OWNER_CAPACITY) {
285	            throw new CityCapacityExceededException(city);
286	        }
287	    }
288	
289	    /**
290	     * Builds the customer code assigned to a newly created owner. The code is formatted as
291	     * {@code '<CITY3>-<LAST3>-<NNNN>'}, where {@code CITY3} is the upper-cased first three letters
292	     * of the owner's city, {@code LAST3} is the upper-cased first three letters of the owner's last
293	     * name and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to one more than the
294	     * number of owners already in that city. For example the seventh owner in {@code 'Springfield'}
295	     * named {@code 'Smith'} is assigned {@code 'SPR-SMI-0007'}.
296	     *
297	     * @param city the owner's city
298	     * @param lastName the owner's last name
299	     * @return the formatted customer code
300	     */
301	    private String nextCustomerCode(String city, String lastName) {
302	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
303	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
304	        long sequence = this.clinicService.findAllOwners().stream()
305	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
306	            .count() + 1L;
307	        return String.format("%s-%s-%04d", city3, last3, sequence);
308	    }
309	
310	    /**
311	     * Counts the existing owners that share the given {@code firstName} and {@code lastName}
312	     * with the owner being created, compared case-insensitively. The count is taken before the
313	     * new owner is persisted, so it reflects only pre-existing owners and never includes the new
314	     * owner itself. The resulting value is stored on the owner and exposed as {@code namesakeCount}.
315	     *
316	     * @param firstName the first name of the owner being created
317	     * @param lastName the last name of the owner being created
318	     * @return the number of pre-existing owners sharing the same first and last name
319	     */
320	    private int countNamesakes(String firstName, String lastName) {
321	        return (int) this.clinicService.findAllOwners().stream()
322	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
323	                && lastName.equalsIgnoreCase(existing.getLastName()))
324	            .count();
325	    }
326	
327	    /**
328	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city}
329	     * or {@code telephone} is missing or blank. A field that is only whitespace is treated as
330	     * blank. When any field fails, a {@link RequiredFieldsMissingException} is thrown carrying
331	     * the names of every offending field, which the exception advice renders as a 400 response
332	     * with an {@code errors} array.
333	     *
334	     * @param ownerFieldsDto the submitted owner fields
335	     */
336	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
337	        List<String> missing = new ArrayList<>();
338	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
339	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
340	        addIfBlank(missing, "address", ownerFieldsDto.getAddress());
341	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
342	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
343	        if (!missing.isEmpty()) {
344	            throw new RequiredFieldsMissingException(missing);
345	        }
346	    }
347	
348	    private void addIfBlank(List<String> missing, String fieldName, String value) {
349	        if (value == null || value.isBlank()) {
350	            missing.add(fieldName);
351	        }
352	    }
353	
354	    /**
355	     * Normalizes a submitted telephone number into E.164 form. Spaces, dashes and brackets
356	     * are stripped. When a leading {@code '+'} and country code are present they are kept as
357	     * given; otherwise the country code {@code '+61'} is assumed and a single leading
358	     * {@code '0'} is dropped from the national digits. The result must be a {@code '+'}
359	     * followed by 8 to 15 digits. The normalized E.164 value is what gets stored and returned.
360	     * When the value cannot form a valid E.164 number an {@link InvalidFieldsException} is
361	     * thrown, which the exception advice renders as a 400 response naming the {@code telephone}
362	     * field. For example {@code "0412 345 678"} becomes {@code "+61412345678"}.
363	     *
364	     * @param telephone the submitted telephone value
365	     * @return the normalized E.164 telephone
366	     */
367	    private String normalizeTelephone(String telephone) {
368	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
369	        String e164;
370	        if (cleaned.startsWith("+")) {
371	            e164 = "+" + cleaned.substring(1);
372	        } else {
373	            String national = cleaned;
374	            if (national.startsWith("0")) {
375	                national = national.substring(1);
376	            }
377	            e164 = "+61" + national;
378	        }
379	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
380	            throw new InvalidFieldsException(List.of("telephone"));
381	        }
382	        return e164;
383	    }
384	
385	    /**
386	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
387	     * and a domain containing at least one dot, none of the parts holding whitespace or a
388	     * second {@code @}.
389	     */
390	    private static final java.util.regex.Pattern EMAIL_PATTERN =
391	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
392	
393	    /**
394	     * Normalizes an optional owner email. An email is optional, so a {@code null} value is
395	     * accepted and returned unchanged. When present it must be a syntactically valid address;
396	     * the value is stored and returned lower-cased. When present but invalid an
397	     * {@link InvalidFieldsException} is thrown, which the exception advice renders as a 400
398	     * response naming the {@code email} field.
399	     *
400	     * @param email the submitted email value, or {@code null} when omitted
401	     * @return the lower-cased email, or {@code null} when none was supplied
402	     */
403	    private String normalizeEmail(String email) {
404	        if (email == null) {
405	            return null;
406	        }
407	        String trimmed = email.trim();
408	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
409	            throw new InvalidFieldsException(List.of("email"));
410	        }
411	        return trimmed.toLowerCase(java.util.Locale.ROOT);
412	    }
413	
414	    /**
415	     * Rejects a new owner whose normalized telephone is already used by any existing owner.
416	     * The telephone is stored in its normalized E.164 form, so a plain equality check
417	     * against every owner's telephone compares E.164 values. When a match is found a
418	     * {@link DuplicateTelephoneException} is thrown, which the exception advice renders as a
419	     * 409 Conflict response.
420	     *
421	     * @param telephone the normalized telephone of the owner being created
422	     */
423	    private void rejectDuplicateTelephone(String telephone) {
424	        boolean taken = this.clinicService.findAllOwners().stream()
425	            .anyMatch(existing -> telephone.equals(existing.getTelephone()));
426	        if (taken) {
427	            throw new DuplicateTelephoneException(telephone);
428	        }
429	    }
430	
431	    /**
432	     * Rejects a new owner whose {@code lastName} and {@code address} already belong to another
433	     * owner, i.e. one that shares its household (see {@link #findHouseholdMate(String, String)}
434	     * for how that identity is compared). A request may bypass this rule by setting
435	     * {@code sharesHousehold} to {@code true}, allowing several owners to share one household.
436	     * When a household mate is found and the request did not opt in a
437	     * {@link DuplicateHouseholdException} is thrown, which the exception advice renders as a 409
438	     * Conflict response.
439	     *
440	     * @param ownerFieldsDto the submitted owner fields
441	     */
442	    private void rejectDuplicateHousehold(OwnerFieldsDto ownerFieldsDto) {
443	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
444	            return;
445	        }
446	        boolean taken = findHouseholdMate(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress()).isPresent();
447	        if (taken) {
448	            throw new DuplicateHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
449	        }
450	    }
451	
452	    /**
453	     * Assigns the shared {@code householdId} for an owner created with {@code sharesHousehold}
454	     * set to {@code true}. The identifier is derived deterministically from the owner's
455	     * household identity (its {@code lastName} and {@code address}, see
456	     * {@link #householdIdFor(String, String)}), so every owner in the same household resolves to
457	     * the same stable value. The new owner receives that value, and any existing household mates
458	     * that do not yet carry it are updated so the whole household shares one identifier. When the
459	     * request did not opt in the owner is left without a household identifier.
460	     *
461	     * @param owner the newly created owner, mutated in place with its household identifier
462	     * @param ownerFieldsDto the submitted owner fields carrying the {@code sharesHousehold} flag
463	     */
464	    private void assignHousehold(Owner owner, OwnerFieldsDto ownerFieldsDto) {
465	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
466	            return;
467	        }
468	        String householdId = householdIdFor(owner.getLastName(), owner.getAddress());
469	        owner.setHouseholdId(householdId);
470	        for (Owner mate : findHouseholdMates(owner.getLastName(), owner.getAddress())) {
471	            if (!householdId.equals(mate.getHouseholdId())) {
472	                mate.setHouseholdId(householdId);
473	                this.clinicService.saveOwner(mate);
474	            }
475	        }
476	    }
477	
478	    /**
479	     * Derives the stable {@code householdId} shared by every owner in the household identified by
480	     * the given {@code lastName} and {@code address}. The two fields are normalized exactly as
481	     * household identity is compared elsewhere (case-insensitively, with collapsed whitespace) and
482	     * hashed with SHA-256, so any two owners in the same household — regardless of creation order —
483	     * resolve to the same identifier. The result is formatted as {@code 'HH-<16 hex chars>'}.
484	     *
485	     * @param lastName the household's last name
486	     * @param address the household's address
487	     * @return the deterministic household identifier
488	     */
489	    private String householdIdFor(String lastName, String address) {
490	        String key = collapseWhitespace(lastName).toLowerCase(java.util.Locale.ROOT) + "|"
491	            + normalizeAddress(address).toLowerCase(java.util.Locale.ROOT);
492	        try {
493	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
494	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
495	            StringBuilder sb = new StringBuilder();
496	            for (int i = 0; i < 8; i++) {
497	                sb.append(String.format("%02X", digest[i]));
498	            }
499	            return "HH-" + sb;
500	        }
501	        catch (java.security.NoSuchAlgorithmException e) {
502	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
503	        }
504	    }
505	
506	    /**
507	     * Finds an existing owner that shares a household with the given {@code lastName} and
508	     * {@code address}. When several owners match, the first one encountered is returned.
509	     *
510	     * @param lastName the last name to match on
511	     * @param address the address to match on
512	     * @return the first owner sharing the household, or empty when none exists
513	     */
514	    private Optional<Owner> findHouseholdMate(String lastName, String address) {
515	        return findHouseholdMates(lastName, address).stream().findFirst();
516	    }
517	
518	    /**
519	     * Finds every existing owner that shares a household with the given {@code lastName} and
520	     * {@code address}. Both fields are compared case-insensitively and with runs of whitespace
521	     * collapsed to a single space (and surrounding whitespace trimmed), so for example
522	     * {@code "Franklin"} at {@code "110  W. Liberty St."} matches {@code "franklin"} at
523	     * {@code "110 W. Liberty St."}. This is the single definition of household identity shared by
524	     * every rule that reasons about households.
525	     *
526	     * @param lastName the last name to match on
527	     * @param address the address to match on
528	     * @return the owners sharing the household, in encounter order (possibly empty)
529	     */
530	    private List<Owner> findHouseholdMates(String lastName, String address) {
531	        String normalizedLastName = collapseWhitespace(lastName);
532	        String normalizedAddress = normalizeAddress(address);
533	        return this.clinicService.findAllOwners().stream()
534	            .filter(existing -> normalizedLastName.equalsIgnoreCase(collapseWhitespace(existing.getLastName()))
535	                && normalizedAddress.equalsIgnoreCase(normalizeAddress(existing.getAddress())))
536	            .toList();
537	    }
538	
539	    /**
540	     * Collapses a field for household comparison: leading and trailing whitespace is trimmed and
541	     * every internal run of whitespace is reduced to a single space. A {@code null} value collapses
542	     * to the empty string. Case is left untouched so callers can compare case-insensitively.
543	     *
544	     * @param value the value to collapse, or {@code null}
545	     * @return the whitespace-collapsed value, never {@code null}
546	     */
547	    private String collapseWhitespace(String value) {
548	        if (value == null) {
549	            return "";
550	        }
551	        return value.trim().replaceAll("\\s+", " ");
552	    }
553	
554	    /**
555	     * Common street-type abbreviations expanded during address normalization, keyed by their
556	     * upper-cased token.
557	     */
558	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS =
559	        java.util.Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
560	
561	    /**
562	     * Normalizes a submitted address into the canonical form stored and returned for an owner:
563	     * leading and trailing whitespace is trimmed, every internal run of whitespace is collapsed to
564	     * a single space, the value is upper-cased, and common street-type abbreviations are expanded
565	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value
566	     * normalizes to the empty string, and an address that holds only whitespace normalizes to the
567	     * empty string so the required-field check rejects it. For example {@code "  12  main  st "}
568	     * becomes {@code "12 MAIN STREET"}. This is the single definition of address normalization used
569	     * everywhere an address is stored or compared.
570	     *
571	     * @param address the submitted address value, or {@code null}
572	     * @return the normalized address, never {@code null}
573	     */
574	    private String normalizeAddress(String address) {
575	        if (address == null) {
576	            return "";
577	        }
578	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
579	        if (collapsed.isEmpty()) {
580	            return "";
581	        }
582	        String[] tokens = collapsed.split(" ");
583	        StringBuilder sb = new StringBuilder(collapsed.length());
584	        for (int i = 0; i < tokens.length; i++) {
585	            if (i > 0) {
586	                sb.append(' ');
587	            }
588	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
589	        }
590	        return sb.toString();
591	    }
592	}
